def f(I):
    h=len(I); w=len(I[0])
    bgc,cs=cc(I)
    big=max(cs,key=len)
    rs=[a for a,b in big]; cl=[b for a,b in big]
    r0,r1,c0,c1=min(rs),max(rs),min(cl),max(cl)
    pm=[[I[i][j]!=bgc for j in range(c0,c1+1)] for i in range(r0,r1+1)]
    fh=[r[::-1] for r in pm]; fv=pm[::-1]
    hh,ww=len(pm),len(pm[0])
    out=[r[:] for r in I]
    for c in cs:
        if c is big: continue
        col=Counter(I[a][b] for a,b in c).most_common(1)[0][0]
        ci=sum(a for a,b in c)/len(c); cj=sum(b for a,b in c)/len(c)
        dr=-1 if ci<r0 else (1 if ci>r1 else None)
        dc=-1 if cj<c0 else (1 if cj>c1 else None)
        def paint(T,pos):
            for i in range(len(T)):
                for j in range(len(T[0])):
                    if T[i][j]:
                        x=pos[0]+i; y=pos[1]+j
                        if 0<=x<h and 0<=y<w and out[x][y]==bgc:
                            out[x][y]=col
        if dc==-1: paint(fh,(r0,c0-ww))
        elif dc==1: paint(fh,(r0,c1+1))
        elif dr==-1: paint(fv,(r0-hh,c0))
        else: paint(fv,(r1+1,c0))
    return out

def solve(I):
    h,w=len(I),len(I[0])
    bgc,cs=comps(I)
    big=max(cs,key=len)
    rs=[a for a,b in big]; cl=[b for a,b in big]
    r0,r1,c0,c1=min(rs),max(rs),min(cl),max(cl)
    pm=[[I[i][j]!=bgc for j in range(c0,c1+1)] for i in range(r0,r1+1)]
    fh=[r[::-1] for r in pm]; fv=pm[::-1]
    out=[r[:] for r in I]
    hh=len(pm); ww=len(pm[0])
    def paint(T,pos,col):
        hh_,ww_=len(T),len(T[0])
        for i in range(hh_):
            for j in range(ww_):
                if T[i][j]:
                    x=pos[0]+i; y=pos[1]+j
                    if 0<=x<h and 0<=y<w and out[x][y]==bgc:
                        out[x][y]=col
    for c in cs:
        if c is big: continue
        col=Counter(I[a][b] for a,b in c).most_common(1)[0][0]
        ci=sum(a for a,b in c)/len(c); cj=sum(b for a,b in c)/len(c)
        dr=-1 if ci<r0 else (1 if ci>r1 else None)
        dc=-1 if cj<c0 else (1 if cj>c1 else None)
        if dc==-1: T,p=(fh,(r0,c0-ww))
        elif dc==1: T,p=(fh,(r0,c1+1))
        elif dr==-1: T,p=(fv,(r0-hh,c0))
        elif dr==1: T,p=(fv,(r1+1,c0))
        paint(T,p,col)
    return out
